// ─── Helpers ──────────────────────────────────────────────────────────────────

interface CBProps {
  label: string;
  checked: boolean;
  onChange: (v: boolean) => void;
  readOnly?: boolean;
}

const CB: React.FC<CBProps> = ({ label, checked, onChange, readOnly }) => (
  <Checkbox
    label={label}
    checked={checked}
    onChange={(e) => onChange(e.target.checked)}
    disabled={readOnly}
    className={readOnly ? styles.checkItemReadOnly : styles.checkItem}
  />
);

export interface CBItem {
  label: string;
  checked: boolean;
  onChange: (v: boolean) => void;
}

/** Renders a list of checkboxes. In readOnly mode, only checked items are shown.
 *  If no items are checked in readOnly mode, shows a fallback message. */
const CBList: React.FC<{ items: CBItem[]; readOnly?: boolean; gridClass?: string; noOptionLabel?: string }> = ({
  items,
  readOnly,
  gridClass,
  noOptionLabel = 'Không có option được chọn',
}) => {
  const visible = readOnly ? items.filter((i) => i.checked) : items;
  if (readOnly && visible.length === 0) {
    return <span className={styles.noOption}>{noOptionLabel}</span>;
  }
  return (
    <div className={gridClass ?? styles.checkGrid}>
      {visible.map((item, idx) => (
        <CB key={idx} label={item.label} checked={item.checked} onChange={item.onChange} readOnly={readOnly} />
      ))}
    </div>
  );
};

// ─── Incident type group row ──────────────────────────────────────────────────

interface GroupRowProps {
  index: number;
  title: string;
  leftItems: CBItem[];
  rightItems?: CBItem[];
  readOnly?: boolean;
  noOptionLabel?: string;
}

const GroupRow: React.FC<GroupRowProps> = ({ index, title, leftItems, rightItems, readOnly, noOptionLabel = 'Không có option được chọn' }) => {
  const hasRight = (rightItems?.length ?? 0) > 0;

  // ── Edit mode ──────────────────────────────────────────────────────────────
  if (!readOnly) {
    return (
      <tr>
        <td className={styles.groupTitle}>{index}. {title}</td>
        <td className={hasRight ? styles.tdNoBorderRight : undefined} colSpan={hasRight ? 1 : 2}>
          <div className={styles.checkGrid}>
            {leftItems.map((item, idx) => (
              <CB key={idx} label={item.label} checked={item.checked} onChange={item.onChange} />
            ))}
          </div>
        </td>
        {hasRight && (
          <td>
            <div className={styles.checkGrid}>
              {rightItems!.map((item, idx) => (
                <CB key={idx} label={item.label} checked={item.checked} onChange={item.onChange} />
              ))}
            </div>
          </td>
        )}
      </tr>
    );
  }

  // ── Read-only mode ─────────────────────────────────────────────────────────
  const leftChecked  = leftItems.filter((i) => i.checked);
  const rightChecked = (rightItems ?? []).filter((i) => i.checked);
  const bothEmpty    = leftChecked.length === 0 && rightChecked.length === 0;

  // Both columns empty → one message spanning both content columns
  if (bothEmpty) {
    return (
      <tr>
        <td className={styles.groupTitle}>{index}. {title}</td>
        <td colSpan={2}>
          <span className={styles.noOption}>{noOptionLabel}</span>
        </td>
      </tr>
    );
  }

  // No right items defined → left spans both columns, no right td
  if (!hasRight) {
    return (
      <tr>
        <td className={styles.groupTitle}>{index}. {title}</td>
        <td colSpan={2}>
          <div className={styles.checkGrid}>
            {leftChecked.map((item, idx) => (
              <CB key={idx} label={item.label} checked={item.checked} onChange={item.onChange} readOnly />
            ))}
          </div>
        </td>
      </tr>
    );
  }

  // Normal case: show checked items per column; if one side is empty just leave it blank
  return (
    <tr>
      <td className={styles.groupTitle}>{index}. {title}</td>
      <td className={styles.tdNoBorderRight}>
        {leftChecked.length > 0 && (
          <div className={styles.checkGrid}>
            {leftChecked.map((item, idx) => (
              <CB key={idx} label={item.label} checked={item.checked} onChange={item.onChange} readOnly />
            ))}
          </div>
        )}
      </td>
      <td>
        {rightChecked.length > 0 && (
          <div className={styles.checkGrid}>
            {rightChecked.map((item, idx) => (
              <CB key={idx} label={item.label} checked={item.checked} onChange={item.onChange} readOnly />
            ))}
          </div>
        )}
      </td>
    </tr>
  );
};

